const { seg, lerp, eo, eio } = kit;
kit.scene('react', {
  init(kit) {
    const M = W.MOODS.hallSage;
    kit.stage.append(kit.h('<div class="ground"><div class="layer react-cam"><svg class="art" viewBox="0 0 1920 1080">' + W.bg.stoneRoom(M, { seed: 9, floorY: 1200 }) + W.glow(1260, 420, 700, '#FFF6D8', 0.5) +
      W.person('react-n', Object.assign({}, W.NARRATOR, { item: null })) + '</svg></div><div class="vignette"></div><p class="hand-label big react-label" style="left:130px;top:360px">Consciousness?</p></div>'));
    this.m = W.bindPerson(kit.stage, 'react-n');
    this.cam = kit.stage.querySelector('.react-cam'); this.label = kit.stage.querySelector('.react-label');
  },
  render(t) {
    this.cam.style.transformOrigin = '1250px 500px';
    this.cam.style.transform = 'scale(' + lerp(1.0, 1.05, eio(seg(t, 0, 1.7))).toFixed(4) + ')';
    const tr = W.tremble(t, 0.32, 0.75);
    W.posePerson(this.m, { x: 1360 + tr, y: 1290, s: 3.4, expr: t < 0.2 ? 'neutral' : 'worried', sq: W.take(t, 0.2), head: lerp(0, -7, eio(seg(t, 0.2, 0.5))), a1: -8, b1: 8, blink: W.blinkAt(t, [1.4]) });
    W.pop(this.label, t, 0.24, 'left');
  },
});
